#[derive(PartialEq, Eq, Debug, Copy, Clone)]
pub struct Options {
    pub across: bool,
}

impl Options {
    #[must_use]
    pub fn direction(self) -> Direction {
        if self.across {
            Direction::LeftToRight
        } else {
